insert into public.hub_market_items (id, seller_name, title, description, images, price, location, contact_phone, category, condition, status, is_test, is_featured, spec_year, spec_mileage, spec_hp, spec_zero_to_100, spec_top_speed, spec_brand, spec_model, created_at) values
  (101, 'Juan M.', 'Toyota Supra MK4', '2JZ armado, interior restaurado y listo para calle/pista. Incluye sistema de escape deportivo, frenos mejorados y un historial de mantenimiento completo. El auto ha sido pulido recientemente, con pintura en impecable estado y detalles interiores renovados para ofrecer una experiencia de conducción tanto para uso diario como para eventos. Se entrega con documentación al día y una inspección mecánica reciente que certifica el excelente estado de todos sus componentes.', array['assets/imgs/supra-white.webp', 'assets/imgs/supra-mk4-2.webp', 'assets/imgs/supra-mk4-3.webp'], 130000, 'Santo Domingo', '8095550134', 'vehiculos'::public.hub_market_category, null, 'aprobado', false, true, 1994, 180000, 873, 3.8, 350, 'Toyota', 'Supra', '2026-04-12'),
  (102, 'AutoHub Garage', 'Volkswagen Golf MK4', 'Project car con upgrades de suspensión y frenos.', array['assets/imgs/vw-golf-mk4.webp'], 8000, 'Santiago', null, 'vehiculos'::public.hub_market_category, null, 'aprobado', false, true, 2003, 210000, 325, 10, 220, 'Volkswagen', 'Golf', '2026-04-08'),
  (103, 'Carlos R.', 'Citroen C3', 'Uso diario, mantenimiento al dia y pintura reciente.', array['assets/imgs/citroen-c3.jpg'], 5000, 'La Romana', null, 'vehiculos'::public.hub_market_category, null, 'aprobado', false, true, 2003, 185000, 110, 14.9, 180, 'Citroen', 'C3', '2026-04-01'),
  (201, 'Racing Parts RD', 'Discos Brembo GTR', 'Set de discos ventilados, poco uso y sin alabeo.', array['assets/imgs/hub-parts/disco-brembo-gtr-2.jpg'], 600, 'Santo Domingo', '8295550187', 'piezas'::public.hub_market_category, null, 'aprobado', false, false, null, null, null, null, null, null, null, '2026-04-18'),
  (202, 'Miguel P.', 'Disco Brembo GTR (Unidad)', 'Unidad individual, ideal para reemplazo rapido.', array['assets/imgs/hub-parts/disco-brembo-gtr-3.jpg'], 180, 'Bani', null, 'piezas'::public.hub_market_category, null, 'aprobado', false, false, null, null, null, null, null, null, null, '2026-04-10'),
  (301, 'Accesorios Hub', 'Pack accesorios interior', 'Kit de accesorios universales para interior deportivo.', array['assets/imgs/catalog/accesorios.jpg'], 120, 'San Cristobal', '8495550142', 'accesorios'::public.hub_market_category, null, 'aprobado', false, false, null, null, null, null, null, null, null, '2026-03-29'),
