  (105, 'X AutoHub', 'PRUEBA - Publicacion de prueba', 'Publicacion de prueba del equipo de X AutoHub. No esta a la venta.', array['assets/imgs/catalog/accesorios.jpg'], 100, 'Santo Domingo', '8099539782', 'accesorios'::public.hub_market_category, null, 'aprobado', true, false, null, null, null, null, null, null, null, '2026-08-15')
insert into public.news (id, title, text, text_large, image_url, images, scope, author, published_at, is_test) values
  (1, '809 Expo por primera vez en RD 🇩🇴', 'Evento con Car Show, Drift exhibition y entretenimiento en vivo. Con los mejores pilotos y proyectos de US y RD.', 'Por primera ves en Republica Dominicana. @809expo Presentado por 100X35 Expo y Clean Culture, traen AutoShow / Drift / Caribbean Culture en un evento con @adam_lz y amigos. El evento tendra lugar en el Autodromo de las Americas este Domingo 7 de Junio de 2026. Sera una experiencia de dia completo con seccion de Car Show, seccion de Drift, Vendor midway, entretenimiento en vivo y la premiacion de los mejores carros del evento. Podras registrar tu vehiculo para el evento proximamente en: cleancultureevents.com', 'assets/imgs/news/expo-809.jpg', array['assets/imgs/news/expo-809.jpg'], 'local'::public.news_scope, null, '2026-04-15', false),
  (2, 'Primer Mercedes Benz completamente electrico', 'Mercedes ha lanzado su primer modelo totalmente electrico, el Mercedes C-Class. Un sedan con las ultimas tecnologias y comfort.', 'Así que, ¡que empiece el juego! Después de que BMW nos impresionara a todos con su revolucionario iX3, elegido Coche del Año por TG, y lo complementara con el magnífico sedán i3, Mercedes ha contraatacado: tras el GLC Electric llega este, el primer Mercedes-Benz Clase C totalmente eléctrico. Y el dato más destacado para muchos será su autonomía, porque… aún se queda corta en comparación con BMW. Mercedes anuncia hasta 760 kilómetros (473 millas) con una sola carga de su batería de 94 kWh, que, como bien saben los entusiastas de los coches eléctricos, es más pequeña que la batería que Múnich ha instalado en el i3. ¿Y para el resto de ustedes? Su aspecto. Este Clase C eléctrico incorpora la última versión del lenguaje de diseño de Mercedes, y la marca afirma que su "silueta de coupé" y su "expresivo diseño trasero GT" dan como resultado una "elegancia con un carisma impresionante".', 'assets/imgs/news/electric-mercedes.png', array['assets/imgs/news/electric-mercedes.png'], 'internacional'::public.news_scope, null, '2026-04-18', false),
  (3, 'PRUEBA - Noticia de prueba', 'Noticia de prueba del equipo de X AutoHub. No es contenido real.', 'Noticia de prueba del equipo de X AutoHub. Sirve para verificar la portada, la galeria y la pagina de detalle sin publicar nada al publico. No es contenido real.', 'assets/imgs/news/expo-809.jpg', array['assets/imgs/news/expo-809.jpg'], 'local'::public.news_scope, null, '2026-08-15', true)
insert into public.social_clubs (id, name, location, focus, description, image_url, members, is_official) values
  (1, 'Supra Club RD', 'Santo Domingo', 'JDM / Performance', 'Duenos y fanaticos de la Supra en Republica Dominicana. Meets mensuales y compras grupales de piezas.', 'assets/imgs/supra-mk4-2.webp', 312, true),
  (2, 'MK4 Crew', 'Santiago', 'Volkswagen / Project cars', 'Todo lo relacionado con la plataforma MK4. Asesoria entre miembros, herramientas compartidas y caravanas.', 'assets/imgs/vw-golf-mk4.webp', 178, false),
  (3, 'Citroen Crew', 'Distrito Nacional', 'Europeos / Daily drivers', 'Comunidad enfocada en mantener europeos economicos rodando. Piezas usadas verificadas y talleres de confianza.', 'assets/imgs/auto-hub/c3.jpeg', 94, false),
  (4, 'Offroad 809', 'La Vega', 'Pickups / 4x4', 'Rutas de fin de semana, montaje de barras LED y suspension elevada. Se recorre el pais completo.', 'assets/imgs/auto-hub/amarok.jpeg', 205, false)
insert into public.social_posts (id, author_name, author_club, text, image_url, tags, likes, comments, created_at) values
  (1, 'Juan M.', 'Supra Club RD', 'Terminamos el armado del 2JZ despues de tres meses. Suena mejor de lo que esperaba. Gracias a todos los que ayudaron con las piezas.', 'assets/imgs/supra-white.webp', array['2JZ', 'Supra', 'BuildLog'], 184, 32, '2026-08-09T18:30:00'),
  (2, 'AutoHub Garage', null, 'Recordatorio: los coilovers Street Pro que estaban agotados ya volvieron al catalogo. Instalacion incluida esta semana.', 'assets/imgs/hub-parts/coilover-street-pro.jpg', array['Suspension', 'Catalogo'], 96, 11, '2026-08-08T14:05:00'),
  (3, 'Carlos R.', 'Citroen Crew', 'Mi C3 cumplio 20 anos rodando y sigue firme. Mantenimiento al dia y cero problemas. Los clasicos economicos tambien cuentan.', 'assets/imgs/citroen-c3.jpg', array['Citroen', 'DailyDriver'], 61, 8, '2026-08-07T09:20:00'),
  (4, 'Laura P.', 'MK4 Crew', 'Buscando quien haya hecho el swap de frenos delanteros en un Golf MK4. Quiero saber que kit usaron antes de comprar.', 'assets/imgs/vw-golf-mk4.webp', array['Golf', 'Frenos', 'Ayuda'], 43, 27, '2026-08-05T20:45:00')
insert into public.social_events (id, title, event_date, location, organizer, description, image_url, attendees, price) values
  (1, '809 Expo — Car Show & Drift', '2026-09-07', 'Autodromo de las Americas', '100X35 Expo / Clean Culture', 'Car show, exhibicion de drift, vendor midway y premiacion de los mejores proyectos del pais.', 'assets/imgs/news/expo-809.jpg', 1240, 1500),
  (2, 'Caravana Hub — Ruta Sur', '2026-09-21', 'Salida desde Santo Domingo', 'X AutoHub', 'Caravana abierta hasta Barahona. Punto de encuentro a las 6:00 AM, desayuno y paradas fotograficas.', 'assets/imgs/auto-hub/tiguan.jpeg', 86, 0),
  (3, 'Track Day — Novatos', '2026-10-05', 'Autodromo de las Americas', 'X AutoHub / Supra Club RD', 'Sesion guiada para quienes nunca han pisado pista. Incluye inspeccion tecnica previa e instructor.', 'assets/imgs/supra-mk4-3.webp', 48, 3500)
